import { getLvcnFontStyle } from '@/lib/lvcn-fonts';
import { cn } from '@/lib/utils';
import { TextInput } from '@/components/ui/primitives';
import { Platform } from 'react-native';

function Input({
  className,
  placeholderClassName,
  style,
  ...props
}: React.ComponentProps<typeof TextInput> & React.RefAttributes<TextInput>) {
  return (
    <TextInput
      className={cn('text-foreground flex h-10 w-full min-w-0 flex-row items-center shadow-sm shadow-black/5 sm:h-9 dark:bg-input/30 border-input disabled:bg-input/50 dark:disabled:bg-input/80 min-h-8 rounded-none border bg-transparent px-2.5 py-1 text-xs transition-colors file:min-h-6 file:text-xs file:font-medium md:text-xs',
        props.editable === false &&
          cn(
            'opacity-50',
            Platform.select({ web: 'disabled:pointer-events-none disabled:cursor-not-allowed' })
          ),
        Platform.select({
          web: cn(
            'placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground outline-none transition-[color,box-shadow] md:text-sm',
            'focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]',
            'aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive'
          ),
          native: 'placeholder:text-muted-foreground/50',
        }),
        className
      )}
      style={[style, getLvcnFontStyle(className)]}
      {...props}
    />
  );
}

export { Input };
